$("#account").submit( evt => {
  let isValid = true;
  const name = $("#name").val().trim();
  const age = parseInt($("#age").val());
  const phone = $("#phone").val().trim();

  if (name === "") { $("#name").next().text("This field is required."); isValid = false; }
  else { $("#name").next().text(""); }

  if (isNaN(age) || age < 18 || age > 120) { $("#age").next().text("Enter an age from 18 to 120."); isValid = false; }
  else { $("#age").next().text(""); }

  if (!/^\d{3}-\d{3}-\d{4}$/.test(phone)) { $("#phone").next().text("Use 999-999-9999 format."); isValid = false; }
  else { $("#phone").next().text(""); }

  if (!isValid) {
    evt.preventDefault();
  }
});

