$("#username").on("input", function() {
  const value = $(this).val();
  let message;
  if (value.length < 4) {
    message = "At least 4 characters";
  } else if (!/^[A-Za-z0-9]+$/.test(value)) {
    message = "Letters and digits only";
  } else {
    message = "Looks good!";
  }
  $("#hint").text(message).toggleClass("ok", message === "Looks good!");
});
